INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/11/09/le-nasdaq-a-rebondi-vendredi-mais-quatre-semaines-de-baisse-testent-le-biais-de-recence',
  'behaviour',
  'article',
  'Le Nasdaq a rebondi vendredi, mais quatre semaines de baisse testent le biais de récence',
  'Un rebond de 1,1 % vendredi a suivi une chute de 5,5 % jeudi, mais le Nasdaq a perdu 3,4 % sur la semaine. Une bonne séance ne règle pas une décision de portefeuille.',
  '<ul>
<li><strong>Le Nasdaq a reculé de 5,</strong><span> Le Nasdaq a reculé de 5,5&nbsp;% jeudi avant de remonter de 1,1&nbsp;% vendredi.</span></li>
<li><strong>La baisse hebdomadaire est demeurée de 3,</strong><span> La baisse hebdomadaire est demeurée de 3,4&nbsp;%, la quatrième de suite.</span></li>
<li><strong>L’indice des semi-conducteurs a rebondi de 4,</strong><span> L’indice des semi-conducteurs a rebondi de 4,2&nbsp;% vendredi.</span></li>
<li><strong>Une dernière séance marquante peut éclipser en mémoire une tendance plus longue,</strong><span> Une dernière séance marquante peut éclipser en mémoire une tendance plus longue.</span></li>
<li><strong>Les conseillers devraient distinguer un rééquilibrage planifié d’une réaction à la dernière clôture,</strong><span> Les conseillers devraient distinguer un rééquilibrage planifié d’une réaction à la dernière clôture.</span></li>
</ul>',
  '<p>Le rallye de vendredi a donné une clôture rassurante. L’indice composé Nasdaq a gagné 1,1&nbsp;% et l’indice des semi-conducteurs de Philadelphie a progressé de 4,2&nbsp;%, Advanced Micro Devices bondissant de 11&nbsp;%. Mais ce rebond a suivi une chute de 5,5&nbsp;% du Nasdaq jeudi et n’a pas empêché une perte hebdomadaire de 3,4&nbsp;%, la quatrième baisse hebdomadaire consécutive. L’indice demeurait à plus de 10&nbsp;% sous son récent sommet, selon Reuters.</p><h2>Pourquoi la dernière séance semble raconter toute l’histoire</h2><p>Le biais de récence est la tendance à accorder un poids disproportionné au résultat observé le plus récemment. La tentation est particulièrement forte quand la dernière observation est spectaculaire et positive. Vendredi a fourni un récit de renversement net, mais pas un changement net de tendance. L’arithmétique compte&nbsp;: une perte de 5,5&nbsp;% exige un gain d’environ 5,82&nbsp;% pour retrouver la valeur de départ. Un rebond de 1,1&nbsp;% ne récupère qu’une fraction de ce repli.</p><p>Un autre piège comportemental va dans la direction opposée. Après quatre semaines de pertes, les investisseurs peuvent s’ancrer dans l’idée que chaque remontée est vouée à l’échec. Aucune de ces réactions ne découle de la seule série de prix. La bonne question est de savoir si les attentes de bénéfices, les valorisations, les coûts de financement ou les besoins de liquidités personnels de l’investisseur ont suffisamment changé pour justifier une autre répartition.</p><h2>Séparer le signal de marché du signal émotionnel</h2><p>La liquidation de la semaine reflétait des préoccupations quant au coût de construction de l’infrastructure d’IA et à la possibilité d’un examen accru après les élections américaines de mi-mandat. Le rebond de vendredi a montré que des acheteurs restaient disposés à détenir le même thème à des prix plus bas. Il n’a pas prouvé que ces préoccupations étaient dissipées. Reuters a rapporté que l’indice S&amp;P 500 avait perdu 2,7&nbsp;% sur la semaine malgré la progression de vendredi.</p><p>Pour les conseillers, une intervention utile consiste à présenter ensemble le jeudi, le vendredi et la semaine complète plutôt que de commencer par la plus récente clôture. Vérifiez si la pondération cible d’un client est réellement sortie de sa bande de rééquilibrage. Si ce n’est pas le cas, l’urgence d’opérer peut être psychologique plutôt que financière.</p><div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
<div style="background:#f5f5f5;border-bottom:1px solid #d0d0d0;padding:10px 14px;display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;">
<span style="font-size:13px;font-weight:700;color:#111;letter-spacing:0.02em;">NASDAQ&nbsp;: DE JEUDI À VENDREDI</span>
<span style="font-size:20px;font-weight:700;color:#111;">+1,1&nbsp;%</span>
<span style="font-size:13px;color:#6b7280;">▲ REBOND DE VENDREDI</span>
<span style="font-size:11px;color:#888;margin-left:auto;">RENDEMENTS QUOTIDIENS | 5 ET 6 NOV. 2026</span>
</div>
<div style="padding:12px 14px 8px;">
