var labels=["5 NOV.", "6 NOV."],data=[-5.5, 1.1],unit="%";
var svg=el("svg",{viewBox:"0 0 680 300",width:"100%",role:"img","aria-label":"NASDAQ\u00a0: DE JEUDI À VENDREDI\u00a0; 5 NOV.\u00a0: -5,5, 6 NOV.\u00a0: 1,1"});
