var lo=Math.min.apply(null,data),hi=Math.max.apply(null,data),span=Math.max(1,hi-lo);
var yMin=Math.floor((lo-Math.max(span*.18,0.2))*10)/10;
var yMax=Math.ceil((hi+Math.max(span*.18,0.2))*10)/10;
if(lo<0&&hi>0){yMin=Math.min(yMin,lo*1.2);yMax=Math.max(yMax,hi*1.2);}
if(yMin===yMax)yMax=yMin+1;
function xp(i){return margin.left+((i+.5)/data.length)*PW;}
function yp(v){return margin.top+(yMax-v)/(yMax-yMin)*PH;}
function fmt(v){return (Math.abs(v)>=100?v.toFixed(2):Math.abs(v)>=10?v.toFixed(1):v.toFixed(1)).replace(".",",")+(unit==="%"?"\u00a0%":unit==="USD"?"":"");}
for(var t=0;t<=4;t++){
 var val=yMin+(yMax-yMin)*t/4,y=yp(val);
 svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:y,y2:y,stroke:"#ececec","stroke-width":"0.5"}));
 svg.appendChild(el("text",{x:margin.left-8,y:y+3,"text-anchor":"end","font-size":"8.5",fill:"#aaaaaa","font-family":FONT},fmt(val)));
}
svg.appendChild(el("line",{x1:margin.left,x2:margin.left,y1:margin.top,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:margin.top+PH,y2:margin.top+PH,stroke:"#d8d8d8","stroke-width":"1"}));
var zero=yp(Math.max(yMin,Math.min(yMax,0)));
if(yMin<0&&yMax>0)svg.appendChild(el("line",{x1:margin.left,x2:margin.left+PW,y1:zero,y2:zero,stroke:"#a0a0a0","stroke-width":"1","stroke-dasharray":"3,3"}));
var bw=Math.min(84,PW/data.length*.42);
for(var i=0;i<data.length;i++){
 var x=xp(i),y=yp(data[i]),base=(yMin<0&&yMax>0)?zero:yp(Math.max(0,yMin));
 svg.appendChild(el("rect",{x:x-bw/2,y:Math.min(y,base),width:bw,height:Math.max(1,Math.abs(y-base)),fill:data[i]<0?"#9ca3af":"#4a5568",rx:1}));
 var pill=fmt(data[i]),pillW=Math.max(38,pill.length*6+12),pillY=Math.max(2,Math.min(278,y-22));
 svg.appendChild(el("rect",{x:x-pillW/2,y:pillY,width:pillW,height:17,rx:3,fill:"#e8a825"}));
 svg.appendChild(el("text",{x:x,y:pillY+12,"text-anchor":"middle","font-size":"9","font-weight":"700",fill:"#111111","font-family":FONT},pill));
 svg.appendChild(el("text",{x:x,y:margin.top+PH+17,"text-anchor":"middle","font-size":"9",fill:"#999999","font-family":FONT},labels[i]));
}
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-size:10px;color:#888;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Reuters, «&nbsp;U.S. stocks close higher as chips rebound&nbsp;», 6 novembre 2026. Variations en pourcentage de l’indice composé Nasdaq, jeudi et vendredi. | hdq.ca</div>
</div>
</div><p style="font-size:11px;color:#666;">Le graphique reprend la présentation habituelle du 5 novembre, avec les valeurs indiquées à chaque observation. Les valeurs représentées et les périodes sont précisées dans l’en-tête du graphique et la ligne de source.</p><p>La conclusion éditoriale est conditionnelle&nbsp;: la prochaine publication vérifiée pourrait renforcer ou affaiblir cette interprétation. Les conseillers devraient placer au cœur de toute décision la convenance propre à chaque client, sa situation fiscale et son horizon de placement.</p>',
  '<div class="toolkit-section"><div class="toolkit-section-label">Ce qu’ils ressentent</div><p>Les clients tentent d’interpréter les dernières nouvelles liées au comportement sans perdre de vue leurs propres projets. Le Nasdaq a reculé de 5,5&nbsp;% jeudi avant de remonter de 1,1&nbsp;% vendredi. Une distinction claire entre les faits vérifiés et les prévisions aidera à éviter des décisions inutiles.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Cadre de conversation</div><p><strong>Commencer par les faits&nbsp;:</strong> Le Nasdaq a reculé de 5,5&nbsp;% jeudi avant de remonter de 1,1&nbsp;% vendredi.</p><p><strong>Mettre en contexte&nbsp;:</strong> La baisse hebdomadaire est demeurée de 3,4&nbsp;%, la quatrième de suite.</p><p><strong>Revenir au plan&nbsp;:</strong> Demandez si un changement d’objectifs, de liquidités ou de tolérance au risque justifie une mesure dans le portefeuille.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Questions à poser</div><div class="checklist-item">Cette nouvelle a-t-elle changé vos objectifs financiers ou votre échéancier&nbsp;?</div><div class="checklist-item">Quel aspect de cette évolution vous préoccupe le plus&nbsp;?</div><div class="checklist-item">De quelle marge de manœuvre avez-vous besoin au cours des douze prochains mois&nbsp;?</div><div class="checklist-item">Un examen du portefeuille par rapport à votre plan initial vous serait-il utile&nbsp;?</div></div><div class="toolkit-section"><div class="toolkit-section-label">Liste de vérification</div><div class="checklist-item">Confirmer les données et la date du rapport sous-jacent.</div><div class="checklist-item">Examiner l’exposition, la concentration et les besoins de liquidités à court terme.</div><div class="checklist-item">Modéliser au moins deux issues plausibles sans tenir l’une ou l’autre pour certaine.</div><div class="checklist-item">Documenter les objectifs du client et la justification de tout changement.</div><div class="checklist-item">Planifier un suivi après la prochaine publication importante.</div></div><div class="toolkit-section"><div class="toolkit-section-label">Modèle de courriel de suivi</div><div class="email-box" id="respond-email"><strong>Objet&nbsp;:</strong> Un éclairage utile sur le comportement<br><br>Bonjour [Nom du client],<br><br>Le Nasdaq a reculé de 5,5&nbsp;% jeudi avant de remonter de 1,1&nbsp;% vendredi. La baisse hebdomadaire est demeurée de 3,4&nbsp;%, la quatrième de suite.<br><br>Plutôt que de prendre une décision à partir d’un seul titre, je propose que nous examinions ensemble vos objectifs, vos besoins de liquidités et vos répartitions actuelles.<br><br>Une brève conversation cette semaine vous conviendrait-elle&nbsp;?<br><br>[Votre nom]<br><br><em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em></div><button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button></div>',
  '<div class="toolkit-section"><div class="toolkit-section-label">Profils de clients à cibler</div><p><strong>Investisseurs autonomes&nbsp;:</strong> Ceux qui décident à partir des manchettes plutôt que d’un cadre de répartition.</p><p><strong>Propriétaires d’entreprise et retraités&nbsp;:</strong> Ceux dont les besoins de liquidités ou de revenu pourraient amplifier les conséquences de l’évolution comportementale.</p></div><div class="toolkit-section"><div class="toolkit-section-label">L’occasion</div><p>Le Nasdaq a reculé de 5,5&nbsp;% jeudi avant de remonter de 1,1&nbsp;% vendredi. Un conseiller peut traduire les faits en analyse de scénarios personnalisée, sans prétendre prédire les marchés ni les politiques.</p></div><div class="toolkit-section"><div class="toolkit-section-label">Questions de découverte</div><div class="checklist-item">Qu’est-ce qui vous a incité à examiner cette question de plus près&nbsp;?</div><div class="checklist-item">Comment évaluez-vous l’effet sur vos placements actuels&nbsp;?</div><div class="checklist-item">Avez-vous un plan écrit pour un résultat moins favorable&nbsp;?</div><div class="checklist-item">Un examen indépendant vous serait-il utile&nbsp;?</div></div><div class="toolkit-section"><div class="toolkit-section-label">Modèle de courriel de prospection</div><div class="email-box" id="prospect-email"><strong>Objet&nbsp;:</strong> Une question qui mérite d’être posée sur le comportement<br><br>Bonjour [Nom du prospect],<br><br>Le Nasdaq a reculé de 5,5&nbsp;% jeudi avant de remonter de 1,1&nbsp;% vendredi. Le titre est important, mais l’effet sur un portefeuille individuel dépend des avoirs, des objectifs et de l’horizon de placement.<br><br>Je me ferais un plaisir de vous présenter un cadre pratique et succinct pour évaluer les répercussions. Un appel de 15&nbsp;minutes cette semaine vous serait-il utile&nbsp;?<br><br>[Votre nom]<br><br><em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em></div><button class="btn-copy" onclick="copyEmail(''prospect-email'', this)">Copier le courriel</button></div>',
