INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/11/09/le-petrole-recule-sur-lespoir-de-paix-en-iran-sans-que-le-detroit-soit-rouvert',
  'geo',
  'article',
  'Le pétrole recule sur l’espoir de paix en Iran, sans que le détroit soit rouvert',
  'Le WTI a clôturé vendredi à 90,83 $ US, les investisseurs escomptant une désescalade. La perturbation physique et la voie politique vers un accord sont deux enjeux distincts.',
  '<ul>
<li><strong>Le brut WTI a clôturé à 90,</strong><span> Le brut WTI a clôturé à 90,83&nbsp;$&nbsp;US le 6 novembre.</span></li>
<li><strong>C’est 12,</strong><span> C’est 12,8&nbsp;% de moins que la clôture de 104,12&nbsp;$&nbsp;US du 30 octobre.</span></li>
<li><strong>Les attentes de désescalade ont réduit la prime de risque sur le pétrole,</strong><span> Les attentes de désescalade ont réduit la prime de risque sur le pétrole.</span></li>
<li><strong>Les attentes de pourparlers ne sont pas équivalentes à un rétablissement des flux de transport maritime,</strong><span> Les attentes de pourparlers ne sont pas équivalentes à un rétablissement des flux de transport maritime.</span></li>
<li><strong>Les portefeuilles canadiens ont besoin de scénarios tant pour un accord que pour une reprise des perturbations,</strong><span> Les portefeuilles canadiens ont besoin de scénarios tant pour un accord que pour une reprise des perturbations.</span></li>
</ul>',
  '<p>Le recul du pétrole est maintenant assez important pour changer la conversation macroéconomique. Le West Texas Intermediate a clôturé à 90,83&nbsp;$&nbsp;US le baril vendredi 6 novembre, contre 104,12&nbsp;$&nbsp;US le 30 octobre. Cela représente une baisse d’environ 12,8&nbsp;% entre les deux dates de clôture vérifiées. Reuters a attribué la pression hebdomadaire récente aux perspectives de désescalade de la guerre américano-israélienne contre l’Iran.</p><h2>Les marchés escomptent une issue diplomatique</h2><p>La chute du brut n’est pas la preuve que le problème d’approvisionnement physique a déjà disparu. Les marchés évaluent des probabilités, et la possibilité d’un accord peut comprimer une prime de risque géopolitique avant que les conditions de transport maritime ne se normalisent. En octobre, des attaques et l’insécurité autour du détroit d’Ormuz ont contribué à maintenir le pétrole à un niveau élevé. Le marché financier peut réévaluer ce danger plus vite que les pétroliers ne peuvent reprendre leurs traversées habituelles.</p><p>Cet écart compte pour l’inflation et les taux d’intérêt. Un pétrole moins cher, s’il se maintient et se répercute sur les consommateurs, allégerait les prix de l’essence et pourrait réduire la pression sur les banques centrales. Mais un revirement des négociations, de nouvelles attaques ou la persistance des contraintes de transport maritime pourraient rapidement rétablir une partie de la prime. Les investisseurs ne devraient pas transformer le recul d’une semaine en certitude d’un cessez-le-feu.</p><h2>Le Canada se trouve des deux côtés de l’échange</h2><p>Les producteurs d’énergie canadiens profitent généralement de prix du brut plus élevés, tandis que les entreprises à forte consommation de carburant et les consommateurs en supportent le coût. Une baisse du prix du pétrole peut donc améliorer les perspectives d’inflation au pays, même si elle affaiblit certaines attentes de bénéfices dans le secteur de l’énergie. Vendredi, le secteur de l’énergie du TSX a légèrement progressé de 0,2&nbsp;%, rappel que le cours des actions ne suit pas mécaniquement la clôture quotidienne du brut.</p><p>Pour les conseillers, le travail utile consiste à cerner les expositions plutôt qu’à prédire les manchettes diplomatiques. Quantifiez la pondération en énergie du portefeuille, testez la pérennité des dividendes selon des hypothèses de brut plus bas et examinez si les dépenses d’un client sensibles à l’inflation pourraient s’améliorer si les prix restent plus bas. Maintenez un scénario distinct pour une reprise des perturbations.</p><div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
